package org.apache.commons.math3.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.MathArithmeticException;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math3.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector.ebeDivide
 */
public class OpenMapRealVector_ebeDivide_TriageGen2Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testEbeDivideNormalCase() {
        double[] values1 = {1.0, 2.0, 3.0, 0.0, 5.0};
        double[] values2 = {2.0, 4.0, 1.0, 0.0, 10.0};
        OpenMapRealVector v1 = new OpenMapRealVector(values1);
        OpenMapRealVector v2 = new OpenMapRealVector(values2);

        OpenMapRealVector result = v1.ebeDivide(v2);

        assertEquals(5, result.getDimension());
        assertEquals(0.5, result.getEntry(0), EPSILON);
        assertEquals(0.5, result.getEntry(1), EPSILON);
        assertEquals(3.0, result.getEntry(2), EPSILON);
        assertEquals(0.0, result.getEntry(3), EPSILON);
        assertEquals(0.5, result.getEntry(4), EPSILON);
    }

    @Test
    public void testEbeDivideWithZeroDenominator() {
        double[] values1 = {1.0, 0.0};
        double[] values2 = {0.0, 2.0};
        OpenMapRealVector v1 = new OpenMapRealVector(values1);
        OpenMapRealVector v2 = new OpenMapRealVector(values2);

        OpenMapRealVector result = v1.ebeDivide(v2);

        // 1.0 / 0.0 should be Double.POSITIVE_INFINITY
        assertEquals(Double.POSITIVE_INFINITY, result.getEntry(0), 0.0);
        // 0.0 / 2.0 should be 0.0
        assertEquals(0.0, result.getEntry(1), EPSILON);
    }

    @Test
    public void testEbeDivideWithNaN() {
        double[] values1 = {0.0};
        double[] values2 = {0.0};
        OpenMapRealVector v1 = new OpenMapRealVector(values1);
        OpenMapRealVector v2 = new OpenMapRealVector(values2);

        OpenMapRealVector result = v1.ebeDivide(v2);

        // 0.0 / 0.0 is NaN
        assertTrue(Double.isNaN(result.getEntry(0)));
    }

    @Test(expected = DimensionMismatchException.class)
    public void testEbeDivideDimensionMismatch() {
        OpenMapRealVector v1 = new OpenMapRealVector(new double[]{1.0, 2.0});
        OpenMapRealVector v2 = new OpenMapRealVector(new double[]{1.0, 2.0, 3.0});
        v1.ebeDivide(v2);
    }

    @Test
    public void testEbeDivideSparseConsistency() {
        // Test that it only iterates through non-zero entries of 'this'
        // as per the implementation logic provided.
        OpenMapRealVector v1 = new OpenMapRealVector(3);
        v1.setEntry(0, 10.0);
        v1.setEntry(2, 20.0);
        // Index 1 is implicitly 0.0

        OpenMapRealVector v2 = new OpenMapRealVector(new double[]{2.0, 5.0, 4.0});

        OpenMapRealVector result = v1.ebeDivide(v2);

        assertEquals(5.0, result.getEntry(0), EPSILON);
        assertEquals(0.0, result.getEntry(1), EPSILON);
        assertEquals(5.0, result.getEntry(2), EPSILON);
    }

    @Test
    public void testEbeDivideEmptyVector() {
        OpenMapRealVector v1 = new OpenMapRealVector(0);
        OpenMapRealVector v2 = new OpenMapRealVector(0);
        OpenMapRealVector result = v1.ebeDivide(v2);
        assertEquals(0, result.getDimension());
    }

    @Test
    public void testEbeDivideNegativeValues() {
        OpenMapRealVector v1 = new OpenMapRealVector(new double[]{-10.0, 10.0});
        OpenMapRealVector v2 = new OpenMapRealVector(new double[]{2.0, -5.0});

        OpenMapRealVector result = v1.ebeDivide(v2);

        assertEquals(-5.0, result.getEntry(0), EPSILON);
        assertEquals(-2.0, result.getEntry(1), EPSILON);
    }
}
